"""B1-2 written tasks from the 2026 sample, grounded in the bundled CSV results."""
import html

def enrich(course):
 prompt2='<p>针对任务一中的两个业务场景，结合分析结果说明其中隐藏的业务和运营价值，并提出相应的改进措施。</p>'
 prompt3='<p>针对任务一中的其中一个业务场景，结合人工智能技术提出解决方案。方案应包括数据使用方式、所选算法模型、业务应用方式和预期效果、验证方法。</p>'
 answer2='''<h4>场景一：预约效率优化</h4><p>按 booking_id 去重后 240 笔，排除已取消后有效预约 216 笔。午间 15/42=35.71%，傍晚 18/54=33.33%，高于上午 6/60=10% 和下午 3/60=5%。午间比例最高，傍晚爽约数量最多，应同时关注比例与数量，不能混为一谈。</p><p><strong>隐藏价值：</strong>识别被占用但未实际使用的时间窗口，减少找房和现场协调成本，提高会议室可获得性。42 次爽约对应 84 个预约小时，仅是历史未使用时长，不能直接承诺全部释放或转化为收益。</p><p><strong>措施：</strong>优先在午间、傍晚做会前提醒和二次确认，提供便捷取消及候补通知。未确认时先提醒、人工核实，确认取消或依已告知的签到规则核实爽约后再释放；不得仅凭模型预测自动取消预约。保留审批或确认及操作记录。</p><h4>场景二：空间匹配优化</h4><p>仅在已使用记录中，以每场 attendees/capacity 的平均值衡量座位利用率。冬青室 12 座、28 场、平均 25%；星河室 16 座、28 场、平均 37.5%，均满足容量≥12、使用≥20场、平均利用率&lt;40%的候选条件。远山室虽有20座，但平均80%，不属于该候选清单。该利用率不是会议室被占用时间的比例。</p><p><strong>隐藏价值：</strong>减少少数人占用大房间的容量浪费，把适配大房间的机会留给确有需求的团队，降低沟通和改约成本。</p><p><strong>措施：</strong>在预约时新增采集预计参会人数及设备需求，在容量和设备满足的前提下推荐更合适的小会议室，由预约人确认后调整，不能仅因历史人数少就强制换房。继续监测座位利用率、匹配率、改约率与用户满意度。</p>'''
 answer3='''<h4>选择场景：预约效率优化——爽约风险辅助提醒</h4><p><strong>数据使用：</strong>历史数据按 booking_id 去重，按题设定义有效预约和爽约标签。用预约前已知的 time_slot、department、room_id、会议室容量、星期及 start_time−booked_at 的提前预约时长构造特征。status 的最终值只用于生成历史标签，不能作为预测特征；实际 attendees 在会后才可确认，也不作为会前预测特征。只使用必要字段，权限分级，设置留存周期。新增提醒、确认、取消、签到、释放及再预约事件日志，为后续验证服务。</p><p><strong>算法模型：</strong>先以“午间/傍晚优先提醒”的规则为基线；数据积累后试用逻辑回归或浅层决策树预测爽约风险，使用分类特征编码并处理类不均衡。历史样本仅覆盖10个工作日，初期可先用规则试点，不能据此承诺模型稳定泛化。训练和验证按时间先后划分，预处理仅在训练数据拟合，必要时开展滚动时间验证。</p><p><strong>业务应用：</strong>预约产生→提取会前特征→计算风险等级→高风险会前提醒和二次确认→预约人保留或取消→按核实的状态及已告知签到规则处理资源释放→通知候补→记录结果。风险分数仅辅助提醒，不替代用户确认和企业规则，不按模型分数直接取消预约。</p><p><strong>预期效果：</strong>目标是减少爽约和空占、提高被释放时段的再预约使用率、减少找房耗时，同时控制额外提醒负担和错误释放。此处为待验证目标，不虚构改善百分比或成本节省金额。</p><p><strong>验证方法：</strong>先做历史时间留出验证，报告爽约类精确率、召回率、F1及样本量、混淆矩阵，并与规则基线比较。再将可比会议室/日期的预约随机分配到原流程与提醒流程，尽量控制跨组干扰并覆盖相同时段；观察至少预先约定的完整周期，不只挑最好的一天。</p><p>线上业务指标：爽约率=爽约笔数/同周期有效预约笔数；释放后再利用率=被释放且又被预约并实际使用的时段数/同周期已释放时段数。同步报告各分母、提醒量、投诉及错误释放事件；比较组间改善和不确定性，结合用户反馈复核，未达到预设目标则调整规则或回退。</p>'''
 course['tasks']=[dict(id='b12t2',title='任务二 · 挖掘隐藏价值',promptHTML=prompt2,answerHTML=answer2),dict(id='b12t3',title='任务三 · 提出解决方案',promptHTML=prompt3,answerHTML=answer3)]
 def slot(answer,wrong,why,groups,aliases=()):return dict(answer=answer,choices=[answer,*wrong],why=why,accepted=list(aliases),matchRule=dict(groups=groups))
 def step(task,title,goal,code,slots,hint):
  solution=code
  for s in slots:solution=solution.replace('{{}}',s['answer'],1)
  course['steps'].append(dict(id='b12-'+str(len(course['steps'])+1),kind='case',taskIndex=task,title=title,goal=goal,code=code,solution=solution,slots=slots,hint=hint,context=''))
 step(0,'任务二：挖掘预约效率价值','从比例与数量两方面解释发现，再提出可执行措施。','午间爽约率 35.71%，傍晚 33.33%；午间比例最高，傍晚数量最多。\n隐藏价值：{{}}。\n措施：优先开展 {{}}。\n释放会议室之前：{{}}。',[
 slot('减少空占并提高会议室可获得性',['只增加预约总次数','全部爽约时长都算已实现收益'],'把未被实际使用的预约窗口转化为可用资源机会，减少找房成本，效果仍需试点验证。',[['空占','空置','闲置','爽约'],['可获得','可用','释放','利用','找房']]),
 slot('会前提醒、二次确认与便捷取消',['直接删除所有晚间预约','仅优化页面颜色'],'午间和傍晚是优先干预时段；提醒后让预约人确认或及时取消。',[['提醒'],['确认','取消']]),
 slot('核实取消或按已告知规则核实爽约',['按风险分数直接取消','一律立即放给他人'],'不能把预测风险当作实际爽约，避免误释放仍然有效的预约。',[['核实','确认','签到'],['取消','爽约','规则']])], '发现→业务价值→干预措施→释放边界，不能只复述两个百分比。')
 step(0,'任务二：挖掘空间匹配价值','候选会议室是冬青室与星河室；改善容量配置时仍要满足业务需要。','冬青室：12座、28场、平均25%；星河室：16座、28场、平均37.5%。\n隐藏价值：{{}}。\n推荐替代会议室必须满足 {{}}。\n预约人确认后调整，跟踪 {{}}。',[
 slot('减少小会占大房的容量浪费',['把爽约人数0混入座位利用率','所有大房间全部停用'],'本任务的平均座位利用率是已使用场次中人数/容量的均值，不是时间占用率。',[['小会','少数人','小团队','人数少','容量'],['大房','大会议室','浪费','匹配']]),
 slot('容量与设备需求',['只比较会议室面积','忽略视频会议设施'],'需新增收集预计参会人数和设备需求；历史实际人数不能直接代表未来会议需求。',[['容量','人数','座位'],['设备','设施']]),
 slot('座位利用率、改约率与用户满意度',['仅统计登录次数','只看推荐点击次数'],'同时衡量资源利用和使用体验，防止为提高指标而制造强制改约。',[['利用率','匹配率'],['满意','改约','体验']])], '数据发现→容量浪费价值→满足约束的推荐→体验与利用效果。')
 step(1,'任务三：选择数据与模型','以爽约风险辅助提醒为例，保留会前信息边界与可解释基线。','特征：时段、部门、会议室、星期和提前预约时长。\n最终status及实际attendees：{{}}。\n先建立时段规则基线，再尝试 {{}}。\n训练验证按 {{}} 划分。',[
 slot('不作为会前预测特征',['直接作为会前特征','使用实际爽约标签预测同一条预约'],'最终状态用于历史标签，实际人数会后才知道，直接当会前输入会造成数据泄漏。',[],['避免数据泄漏','仅使用会前可获得信息']),
 slot('逻辑回归或浅层决策树',['不验证直接用深层模型','按随机编号决定是否爽约'],'给出适合小数据和可解释需求的候选；样本仅10个工作日，先规则试点并积累数据。',[['逻辑回归','决策树']],['逻辑回归','决策树','可解释分类模型']),
 slot('时间先后',['未来训练过去验证','用同一数据拟合再报告训练分数'],'模拟真实未来预测，预处理在训练数据上拟合，避免未来信息泄漏。',[['时间','滚动','过去训练未来验证']])], '数据使用方式、模型及其适用条件都要写，不能只写“用AI预测”。')
 step(1,'任务三：设计应用与预期效果','风险评分用于辅助提醒，资源释放仍受确认和企业规则约束。','业务链：预约→会前特征→风险预测→ {{}}\n→核实状态后释放／保留→候补通知→记录结果。\n目标：{{}}。\n必须同步监测 {{}}。',[
 slot('提醒与二次确认',['按分数直接取消预约','直接强制更换会议室'],'风险高不等于真实爽约，先提醒并请求确认。',[['提醒'],['确认']]),
 slot('减少爽约和空占、提高再利用',['承诺立刻节约固定金额','只提高模型训练准确率'],'明确业务效果但不编造收益，效果需通过试点评估。',[['爽约','空占'],['再利用','复用','利用率','减少','降低']]),
 slot('错误释放、投诉与提醒负担',['只监测点击量','忽略用户投诉'],'效果评价要有保护指标，避免提醒过量和误伤正常预约。',[['误释放','错误释放','误取消','投诉'],['提醒','负担','打扰','投诉']])], '数据→模型→业务动作→可验证目标→保护指标，形成可实施方案。')
 step(1,'任务三：验证模型与业务效果','同时验证离线预测质量与线上真实收益，指标必须有口径。','离线：按时间留出验证，报告 {{}} 并与规则基线比较。\n线上：开展 {{}}，覆盖可比会议室、日期和时段。\n爽约率分母：{{}}。\n再利用率分母：{{}}。',[
 slot('精确率、召回率和F1',['只报训练准确率','不报告样本量'],'指标聚焦爽约类别，并报告样本量、混淆矩阵和误报/漏报，不能以预测指标代替业务收益。',[['精确率','precision'],['召回率','recall'],['f1']]),
 slot('随机对照试点',['干预前后任意各挑一天','只挑效果最好的时段'],'比较原流程与提醒流程，尽量控制跨组干扰，并约定观察周期及回退条件。',[['对照','ab测试','a/b','随机分组']]),
 slot('同周期有效预约笔数',['全部导出行数含重复和取消','所有已使用人数'],'按booking_id去重，排除已取消，与分子爽约笔数使用相同周期。',[['有效预约']]),
 slot('同周期已释放时段数',['全部预约笔数','成功再预约时段数'],'分子是释放后又被预约且实际使用的时段数；分母是同周期全部已释放时段数。',[['已释放','释放的','释放时段']])], '离线评估+线上对照试点；写清指标分子、分母、周期和保护项。')
 course['count']=len(course['steps'])
 course['writtenDownloadPath']='materials/b12-written-reference.html'
 doc='<h1>B1-2 · 任务二与任务三参考答案</h1><p>按2026年样卷要求与原题CSV计算结果整理，仅为一种合理方案，不是唯一标准答案。</p>'+''.join('<h2>'+html.escape(t['title'])+'</h2>'+t['promptHTML']+t['answerHTML'] for t in course['tasks'])
 return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>B1-2任务二、三参考答案</title><style>body{max-width:860px;margin:30px auto;padding:0 20px;font:15px/1.9 sans-serif;color:#294352}h2{margin-top:36px}p{margin:14px 0}</style>'+doc+'</html>'
